<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Http;
use App\Models\{User,MarketingChannelConnection};
class MarketingPostsTest extends TestCase {
 use RefreshDatabase;
 private function actor(){Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);config(['marketing.post_queue_enabled'=>false,'marketing.post_scheduling_enabled'=>false,'services.facebook.client_id'=>'posts-test','marketing.execution_enabled'=>false]);return $u;}
 private function channel($u,$extra=[]){return MarketingChannelConnection::create(array_merge(['merchant_key'=>app(\App\Services\Marketing\MarketingChannels::class)->merchant(),'platform'=>'facebook','provider_account_id'=>'123','app_id'=>'posts-test','name'=>'Test page','access_token'=>'SECRET','permissions'=>['pages_show_list','pages_read_engagement','pages_manage_posts'],'tasks'=>['CREATE_CONTENT'],'authorized_by'=>$u->id,'state'=>'connected'], $extra));}
 private function payload($a=[]){return array_merge(['id'=>(string)\Illuminate\Support\Str::uuid(),'version'=>0,'title'=>'Draft title','copy'=>'Our latest product.','targets'=>[],'copies'=>[],'asset'=>null,'type'=>'Post','tz'=>'Asia/Kuala_Lumpur'],$a);}
 public function test_drafts_are_database_backed_private_and_do_not_probe_providers(){ $u=$this->actor();$p=$this->payload();$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk()->assertJsonPath('post.status','Draft');$this->getJson('/admin/marketing/posts/data')->assertOk()->assertJsonCount(1,'posts')->assertDontSee('SECRET');$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->getJson('/admin/marketing/posts/data')->assertJsonCount(0,'posts');$this->postJson('/admin/marketing/posts/data/draft',$p)->assertNotFound();Http::assertNothingSent(); }
 public function test_schedule_version_cancel_and_repeat_are_safe(){ $u=$this->actor();$c=$this->channel($u);$p=$this->payload(['targets'=>[$c->id],'due'=>now()->addDay()->toIso8601String()]);$r=$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk()->assertJsonPath('post.status','Scheduled');$v=$r->json('post.version');$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertStatus(409);$this->postJson('/admin/marketing/posts/data/cancel',['id'=>$p['id'],'version'=>$v])->assertOk()->assertJsonPath('post.status','Cancelled');$this->assertDatabaseCount('marketing_posts',1);Http::assertNothingSent(); }
 public function test_foreign_disconnected_and_missing_publish_access_are_rejected(){ $u=$this->actor();$c=$this->channel($u,['merchant_key'=>'other']);$this->postJson('/admin/marketing/posts/data/draft',$this->payload(['targets'=>[$c->id]]))->assertUnprocessable();$c=$this->channel($u,['permissions'=>['pages_show_list']]);$p=$this->payload(['targets'=>[$c->id],'due'=>now()->addDay()->toIso8601String()]);$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertUnprocessable();$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk();Http::assertNothingSent(); }
 public function test_past_time_missing_content_and_unknown_asset_block_schedule(){ $u=$this->actor();$c=$this->channel($u);foreach([['due'=>now()->subDay()->toIso8601String()],['copy'=>''],['asset'=>'image:999999']] as $bad){$p=$this->payload(array_merge(['targets'=>[$c->id],'due'=>now()->addDay()->toIso8601String()],$bad));$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertUnprocessable();}Http::assertNothingSent(); }
 public function test_view_only_employee_cannot_write_and_rendering_disabled_does_not_block_drafts(){ $this->actor();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);$u->permissions()->create(['permission'=>'marketing.view']);$this->actingAs($u);$this->get('/admin/marketing/posts')->assertOk();$this->postJson('/admin/marketing/posts/data/draft',$this->payload())->assertForbidden();Http::assertNothingSent(); }
 public function test_fake_attempts_preserve_partial_success_and_unknown_is_never_resent(){ $u=$this->actor();$a=$this->channel($u);$b=$this->channel($u,['provider_account_id'=>'456']);$p=$this->payload(['targets'=>[$a->id,$b->id],'due'=>now()->addDay()->toIso8601String()]);$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();$service=app(\App\Services\Marketing\MarketingPosts::class);$calls=0;$fake=function($target)use(&$calls,$a){$calls++;return $target===$a->id?'Published':'Unknown';};$service->executeFake($p['id'],$fake);$service->executeFake($p['id'],$fake);$this->assertSame(2,$calls);$this->assertDatabaseCount('marketing_post_attempts',2);$this->getJson('/admin/marketing/posts/data')->assertJsonPath('posts.0.outcomes.'.$a->id.'.status','Published')->assertJsonPath('posts.0.outcomes.'.$b->id.'.reason','unknown');$p['version']=2;$this->postJson('/admin/marketing/posts/data/draft',$p)->assertStatus(409);Http::assertNothingSent(); }

 public function test_fake_permission_and_media_failures_keep_successful_destination_immutable(){
  $u=$this->actor();$a=$this->channel($u);$b=$this->channel($u,['provider_account_id'=>'456']);$p=$this->payload(['targets'=>[$a->id,$b->id],'due'=>now()->addDay()->toIso8601String()]);$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk();app(\App\Services\Marketing\MarketingPosts::class)->executeFake($p['id'],fn($t)=>$t===$a->id?'Published':'Media');
  $p['version']=2;$p['copy']='Changed for remaining target';$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk()->assertJsonPath('post.copies.'.$a->id,'Our latest product.')->assertJsonPath('post.outcomes.'.$a->id.'.status','Published')->assertJsonCount(1,'post.approvals');
  $p['version']=3;$this->postJson('/admin/marketing/posts/data/schedule',$p)->assertOk()->assertJsonPath('post.outcomes.'.$a->id.'.status','Published');$count=0;app(\App\Services\Marketing\MarketingPosts::class)->executeFake($p['id'],function()use(&$count){$count++;return 'Permission';});$this->assertSame(1,$count);$this->getJson('/admin/marketing/posts/data')->assertJsonPath('posts.0.outcomes.'.$b->id.'.reason','permission');Http::assertNothingSent();
 }
 public function test_media_library_is_real_and_private_and_unowned_video_cannot_be_attached(){
  $u=$this->actor();$this->getJson('/admin/marketing/posts/library?q=no-such-product')->assertOk()->assertJsonCount(0,'assets');$this->postJson('/admin/marketing/posts/data/draft',$this->payload(['asset'=>'video:'.\Illuminate\Support\Str::uuid().':portrait']))->assertUnprocessable();$this->get('/admin/marketing/posts/media/image:999999')->assertNotFound();Http::assertNothingSent();
 }
 public function test_empty_and_expired_accounts_cannot_schedule_and_invalid_timezone_is_rejected(){
  $u=$this->actor();$c=$this->channel($u,['state'=>'disconnected']);foreach([['targets'=>[]],['targets'=>[$c->id]],['targets'=>[$c->id],'tz'=>'Invalid/Zone']] as $bad)$this->postJson('/admin/marketing/posts/data/schedule',$this->payload($bad+['due'=>now()->addDay()->toIso8601String()]))->assertUnprocessable();Http::assertNothingSent();
 }

 public function test_dated_draft_is_not_scheduling_and_media_paths_never_fetch_remote_files(){
  $this->actor();$p=$this->payload(['due'=>now()->addDay()->toIso8601String()]);$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk()->assertJsonPath('post.status','Draft');$this->assertDatabaseCount('marketing_post_attempts',0);$s=app(\App\Services\Marketing\MarketingPosts::class);$this->assertNull($s->imagePath('https://external.example/image.png'));$this->assertNull($s->imagePath('../.env'));$this->assertNull($s->imagePath('/images/../../.env'));Http::assertNothingSent();
 }
 public function test_fake_execution_is_not_available_outside_testing_and_has_no_web_route(){
  $this->actor();$this->postJson('/admin/marketing/posts/data/execute-fake',$this->payload())->assertNotFound();$original=$this->app['env'];$this->app['env']='local';try{app(\App\Services\Marketing\MarketingPosts::class)->executeFake('unused',fn()=> 'Published');$this->fail('Fake execution must be test-only');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}finally{$this->app['env']=$original;}Http::assertNothingSent();
 }
 public function test_delete_draft_is_scoped_versioned_and_keeps_original_record():void {$this->actor();$p=$this->payload();$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk();$this->postJson('/admin/marketing/posts/data/delete',['id'=>$p['id'],'version'=>9])->assertStatus(409);$this->postJson('/admin/marketing/posts/data/delete',['id'=>$p['id'],'version'=>1])->assertOk()->assertJsonPath('post.deleted',true);$this->getJson('/admin/marketing/posts/data')->assertJsonCount(0,'posts');$this->assertDatabaseHas('marketing_posts',['id'=>$p['id']]);$p['version']=2;$this->postJson('/admin/marketing/posts/data/draft',$p)->assertNotFound();Http::assertNothingSent();}
 public function test_delete_rejects_scheduled_and_published_records_and_other_users():void {$u=$this->actor();$p=$this->payload();$this->postJson('/admin/marketing/posts/data/draft',$p)->assertOk();foreach(['Scheduled','Queued','Publishing','Published'] as $state){\App\Models\MarketingPost::whereKey($p['id'])->update(['status'=>$state]);$this->postJson('/admin/marketing/posts/data/delete',['id'=>$p['id'],'version'=>1])->assertStatus(409);} $this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->postJson('/admin/marketing/posts/data/delete',['id'=>$p['id'],'version'=>1])->assertNotFound();Http::assertNothingSent();}
}
